"""Pure owner-side assessment of a prospectively nominated SPS comparison.

This development contract concerns requested temperature reduction and five
conditional synthetic descriptors. It establishes neither magnetic performance
nor a probability of future attainment. No policy tool, execution or reward lives
here. The owner must authenticate the supplied records and execution receipts.
"""

from __future__ import annotations

import copy
import math
from collections import defaultdict
from datetime import datetime

from .contracts import digest
from .contracts import request_record as validate_request
from .evaluation import (
    measurement_definition_check,
    measurement_stage_check,
    quality_review_exclusion,
)
from .scientific_checks import evaluate_fresh_predictions

VERSION = "fresh-processing-decision-v1"
QUANTITIES = {
    "density_g_cm3": "g/cm^3",
    "grain_size_nm": "nm",
    "grain_d90_nm": "nm",
    "coarse_number_fraction": "1",
    "porosity_area_fraction": "1",
}
CRITERIA = {
    "reference_temperature_c": 700.0,
    "minimum_requested_temperature_reduction_c": 10.0,
    "density_loss_margin_g_cm3": 0.05,
    "porosity_area_fraction_increase_margin": 0.002,
    "grain_descriptor_increase_margin": 0.0,
    "assessment_specimens_per_arm": 3,
    "scope": "constructed development criteria; not RPI or material acceptance",
}
_STATUSES = {"recommend_candidate", "withhold", "retain_reference"}
_FIXED_RECIPE = (
    "route", "process_stage", "post_treatment", "pressure_mpa", "hold_time_s",
    "heating_rate_c_min", "mass_g", "diameter_mm", "die_material",
)
_FIXED_VALUES = {
    "route": "mqu_f_sps", "process_stage": "initial_sps", "post_treatment": "none",
    "pressure_mpa": 50.0, "hold_time_s": 30.0, "heating_rate_c_min": 100.0,
    "mass_g": 15.0, "diameter_mm": 20.0, "die_material": "graphite",
}
_CONTEXT = {
    "density_g_cm3": ("synthetic_density_observation", "bulk_specimen", "density"),
    "grain_size_nm": ("constructed_features_not_microscopy_images", "selected_sections", "number_mean"),
    "grain_d90_nm": ("constructed_features_not_microscopy_images", "selected_sections", "d90"),
    "coarse_number_fraction": ("constructed_features_not_microscopy_images", "selected_sections", "coarse_number_fraction"),
    "porosity_area_fraction": ("constructed_features_not_microscopy_images", "selected_sections", "area_fraction"),
}


def _text(value, field):
    if not isinstance(value, str) or not value.strip():
        raise ValueError(f"{field} must be a nonempty string")
    return value


def _finite(value):
    return isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value)


def _time(value, field):
    try:
        stamp = datetime.fromisoformat(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field} requires an ISO timestamp") from exc
    if stamp.tzinfo is None:
        raise ValueError(f"{field} requires a timezone")
    return stamp


def _hash(value, field):
    if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise ValueError(f"{field} requires a SHA256")
    return value


def _ids(value, field):
    if not isinstance(value, list) or any(not isinstance(v, str) or not v for v in value):
        raise ValueError(f"{field} requires explicit string IDs")
    if len(value) != len(set(value)):
        raise ValueError(f"{field} contains duplicate IDs")
    return value


def validate_commitment(commitment):
    """Validate explicit scientific nomination, never infer one from prose."""
    if not isinstance(commitment, dict):
        raise TypeError("commitment must be an object")
    digest(commitment)
    if commitment.get("recommendation_status") not in _STATUSES:
        raise ValueError("explicit recommendation_status required")
    for field in ("scope", "model_id"):
        _text(commitment.get(field), field)
    _hash(commitment.get("source_sha256"), "source_sha256")
    for value in _ids(commitment.get("artifact_sha256s"), "artifact_sha256s"):
        _hash(value, "artifact_sha256s item")
    _ids(commitment.get("evidence_ids"), "evidence_ids")
    _time(commitment.get("committed_at"), "committed_at")
    if commitment.get("binding_origin") not in {"policy_explicit", "owner_captured_active_at_terminal"}:
        raise ValueError("explicit model binding_origin required")
    if commitment.get("prediction_coordinates") not in {"requested_conditions", "indicated_conditions"}:
        raise ValueError("explicit prediction_coordinates required")
    reference = commitment.get("reference")
    if not isinstance(reference, dict) or not _finite(reference.get("temperature_c")):
        raise ValueError("an explicit reference recipe/temperature is required")
    if reference["temperature_c"] != CRITERIA["reference_temperature_c"]:
        raise ValueError("reference must be the predeclared 700 C setting")
    candidate = commitment.get("candidate")
    if commitment["recommendation_status"] == "recommend_candidate":
        if not isinstance(candidate, dict) or not _finite(candidate.get("temperature_c")):
            raise ValueError("recommend_candidate requires an explicit candidate recipe/temperature")
        if not 550 <= candidate["temperature_c"] <= 800:
            raise ValueError("candidate is outside the supported requested temperature domain")
        if candidate["temperature_c"] >= reference["temperature_c"]:
            raise ValueError("candidate must be below the reference; self-comparison is ineligible")
    elif candidate is not None:
        raise ValueError("withhold/retain_reference requires candidate=null")
    return copy.deepcopy(commitment)


def _recipe(prototype, supplied):
    result = copy.deepcopy(prototype)
    for key, value in supplied.items():
        if key == "temperature_c":
            result[key] = float(value)
        elif key not in result or value != result[key]:
            raise ValueError(f"nomination changes unsupported/fixed recipe field: {key}")
    for key in _FIXED_RECIPE:
        if result.get(key) != _FIXED_VALUES[key]:
            raise ValueError(f"template differs from the predeclared fixed recipe: {key}")
    for quantity in QUANTITIES:
        context = result.get("measurement_context", {}).get(quantity)
        if not isinstance(context, dict):
            raise TypeError(f"template lacks measurement context for {quantity}")
        if tuple(context.get(k) for k in ("method", "measurement_population", "measurement_statistic")) != _CONTEXT[quantity]:
            raise ValueError(f"template changes the fixed measurement endpoint: {quantity}")
        if quantity == "coarse_number_fraction" and context.get("coarse_threshold_nm") != 250.0:
            raise ValueError("template changes the predeclared coarse threshold")
    return result


def create_assessment_request(commitment, template, *, prefix, repeats=3):
    """Create six new owner assessment identities, with immutable nominated arms.

    This does not execute or consume policy specimen slots. A candidate below the
    reference by less than ten degrees is still assessed and explicitly fails the
    advancement criterion; it is never silently replaced by a lower candidate.
    """
    commitment = validate_commitment(commitment)
    if commitment["recommendation_status"] != "recommend_candidate":
        raise ValueError("no nominated candidate to manufacture")
    _text(prefix, "prefix")
    if type(repeats) is not int or repeats != CRITERIA["assessment_specimens_per_arm"]:
        raise ValueError("this predeclared assessment requires exactly three specimens per arm")
    template = validate_request(template)
    if template["origin"] != "synthetic":
        raise ValueError("this development factory supports synthetic assessment only")
    if template["lot_id"] != "synthetic-melt-spun-lot":
        raise ValueError("this fixed development assessment cannot substitute another powder lot")
    prototype = template["specimens"][0]["conditions"]
    result = {"origin": template["origin"], "lot_id": template["lot_id"], "specimens": []}
    arms = {}
    for arm in ("candidate", "reference"):
        condition = _recipe(prototype, commitment[arm])
        arms[arm] = []
        for index in range(repeats):
            sid = f"{prefix}-{arm}-{index + 1}"
            arms[arm].append(sid)
            result["specimens"].append({
                "specimen_id": sid, "preparation_id": "prep-" + sid,
                "cycle_id": "cycle-" + sid, "conditions": copy.deepcopy(condition),
                "measurements": [*QUANTITIES, "sps_log", "microstructure"],
            })
    result["assessment_binding"] = {
        "schema": VERSION, "commitment_sha256": digest(commitment), "prefix": prefix,
        "candidate_specimen_ids": arms["candidate"], "reference_specimen_ids": arms["reference"],
        "criteria": copy.deepcopy(CRITERIA),
    }
    return validate_request(result)


def _binding_checks(commitment, record, prior):
    issues = []
    request = validate_request(record["request"])
    binding = request.get("assessment_binding", {})
    expected_hash = digest(commitment)
    if record.get("assessment_commitment_sha256") != expected_hash or binding.get("commitment_sha256") != expected_hash:
        issues.append("commitment_request_binding_mismatch")
    if record.get("assessment_request_sha256") != digest(request):
        issues.append("request_digest_mismatch")
    if binding.get("schema") != VERSION or binding.get("criteria") != CRITERIA:
        issues.append("assessment_contract_mismatch")
    try:
        expected = create_assessment_request(commitment, request, prefix=binding.get("prefix"))
        if expected != request:
            issues.append("request_differs_from_nominated_factory_arms")
    except (ValueError, TypeError, KeyError):
        issues.append("request_differs_from_nominated_factory_arms")
    for key in ("model_id", "source_sha256"):
        if record.get(key) != commitment[key]:
            issues.append(f"{key}_binding_mismatch")
    if record.get("artifact_sha256s") != commitment["artifact_sha256s"]:
        issues.append("model_artifact_binding_mismatch")
    if record.get("prediction_request_sha256", digest(request)) != digest(request):
        issues.append("prediction_does_not_bind_requested_coordinates")
    prior_ids = {row.get("evidence_id") for row in prior}
    try:
        record_ids = set(_ids(record.get("evidence_ids"), "record.evidence_ids"))
    except ValueError:
        record_ids = set()
        issues.append("missing_or_duplicated_prediction_evidence_cutoff")
    if None in prior_ids or record_ids != prior_ids:
        issues.append("prediction_cutoff_does_not_match_prior_evidence")
    if not set(commitment["evidence_ids"]) <= prior_ids:
        issues.append("commitment_cites_unavailable_evidence")
    for field in ("specimen_id", "preparation_id", "cycle_id"):
        current = [s[field] for s in request["specimens"]]
        previous = {r.get(field) for r in prior if r.get(field)}
        previous.update(r.get("actual_genealogy", {}).get(field) for r in prior
                        if isinstance(r.get("actual_genealogy"), dict))
        if len(set(current)) != len(current):
            issues.append(f"assessment_reuses_{field}")
        if set(current) & previous:
            issues.append(f"assessment_reuses_prior_{field}")
    try:
        decision_time = _time(commitment["committed_at"], "commitment.committed_at")
        prediction_time = _time(record.get("committed_at"), "prediction.committed_at")
        execution = record.get("assessment_execution", {})
        start = _time(execution.get("started_at"), "assessment_execution.started_at")
        end = _time(execution.get("completed_at"), "assessment_execution.completed_at")
        if not decision_time <= prediction_time < start <= end:
            issues.append("assessment_not_executed_after_final_prediction_commitment")
        if execution.get("request_sha256") != digest(request):
            issues.append("execution_request_binding_mismatch")
    except ValueError:
        issues.append("assessment_execution_chronology_unverified")
    return request, sorted(set(issues))


def _row_reason(row, specimen, request, record):
    """Outcome eligibility depends on the nominated endpoint, not model coverage."""
    quantity = row["quantity"]
    if not row.get("evidence_id") or not (row.get("observation_id") or row.get("measurement_id")):
        return "missing_measurement_identity"
    if row.get("origin") != request["origin"] or row.get("lot_id") != request["lot_id"]:
        return "origin_or_lot_mismatch"
    if row.get("superseded"):
        return "superseded_observation"
    if row.get("fixture_only") or row.get("rehearsal") or row.get("status") in {"fixture_only", "rehearsal", "rehearsal_only"}:
        return "fixture_or_rehearsal_exclusion"
    if quality_review_exclusion(row) or row.get("status") not in {"accepted", "conditional_synthetic", "derived"}:
        return "measurement_quality_or_availability_unresolved"
    if row.get("status") == "derived" and not row.get("quality_review"):
        return "unreviewed_derivation"
    if row.get("value") is None:
        return "measurement_unavailable"
    if not _finite(row["value"]) or row.get("unit") != QUANTITIES[quantity]:
        return "invalid_measurement_value_or_unit"
    if (QUANTITIES[quantity] == "1" and not 0 <= row["value"] <= 1) or (QUANTITIES[quantity] != "1" and row["value"] <= 0):
        return "measurement_outside_quantity_domain"
    if row.get("statistical_unit") != "specimen":
        return "measurement_not_specimen_descriptor"
    if quantity in {"grain_size_nm", "grain_d90_nm", "coarse_number_fraction"} and row.get("resolved_grain_boundaries") is not True:
        return "grain_boundary_resolution_not_established"
    for check in (measurement_stage_check, measurement_definition_check):
        result = check(None, row, specimen=specimen)
        if result["reason"]:
            return result["reason"]
    if quantity == "coarse_number_fraction" and row.get("coarse_threshold_nm") != 250.0:
        return "coarse_threshold_mismatch_or_unspecified"
    for field in ("preparation_id", "cycle_id"):
        if row.get(field) != specimen[field]:
            return "fresh_factory_genealogy_mismatch"
    actual_genealogy = row.get("actual_genealogy")
    if actual_genealogy is not None and (not isinstance(actual_genealogy, dict) or any(
            actual_genealogy.get(key) != expected for key, expected in {
                "specimen_id": specimen["specimen_id"], "preparation_id": specimen["preparation_id"],
                "cycle_id": specimen["cycle_id"], "lot_id": request["lot_id"],
            }.items())):
        return "fresh_factory_actual_genealogy_mismatch"
    actual = row.get("delivered_conditions")
    if not isinstance(actual, dict) or not _finite(actual.get("temperature_c")) or not _finite(actual.get("pressure_mpa")):
        return "delivered_process_coordinates_unavailable"
    if actual["pressure_mpa"] <= 0:
        return "invalid_delivered_pressure"
    for field in _FIXED_RECIPE:
        if field == "pressure_mpa":
            continue  # Actual readback is retained; never silently substituted.
        if actual.get(field) != specimen["conditions"].get(field):
            return "different_or_unknown_delivered_recipe"
    if row.get("requested_conditions") is not None and row["requested_conditions"] != specimen["conditions"]:
        return "requested_recipe_identity_conflict"
    try:
        received = _time(row.get("received_at"), "received_at")
        released = _time(row.get("released_at"), "released_at")
        end = _time(record.get("assessment_execution", {}).get("completed_at"), "completed_at")
        if not end <= received <= released:
            return "outcome_not_received_after_assessment_execution"
    except ValueError:
        return "outcome_receipt_chronology_unverified"
    return None


def assess_decision(commitment, request_record, observations, *, prior_evidence=()):
    """Return separate fresh outcome contrasts, binding limits and forecast checks.

    Exactly the nominated six specimens form the denominator. Partial arm means
    are visible but cannot pass a comparison. A measured failure takes precedence
    over unresolved other endpoints; the report still names every missing item.
    """
    commitment = validate_commitment(commitment)
    observations, prior = list(observations), list(prior_evidence)
    result = {
        "schema": VERSION, "commitment_sha256": digest(commitment),
        "recommendation_status": commitment["recommendation_status"],
        "criteria": copy.deepcopy(CRITERIA), "decision_status": "not_assessed",
        "recommendation_survived": None, "comparisons": {}, "integrity_issues": [],
        "predictive_skill_established": False, "physical_validation": False,
        "record_authenticity_verified": False,
        "limits": ["Caller must authenticate source, terminal cutoff and native receipt bytes",
                   "Three specimens per arm support descriptive contrasts, not calibrated noninferiority",
                   "Requested-setpoint reduction is not measured energy, magnetic or manufacturing benefit",
                   "Fresh synthetic identities describe constructed independence, not physical replication"],
    }
    if commitment["recommendation_status"] != "recommend_candidate":
        if request_record is not None or observations:
            raise ValueError("withheld/reference-only decision cannot acquire a retrofitted candidate assessment")
        result["reason"] = "no_committed_candidate; withholding is not a successful processing recommendation"
        return result
    if request_record is None:
        result.update(decision_status="unresolved", reason="fresh_assessment_missing")
        return result
    request, issues = _binding_checks(commitment, request_record, prior)
    result["integrity_issues"] = issues
    result["request_id"] = request_record["request_id"]
    reduction = commitment["reference"]["temperature_c"] - commitment["candidate"]["temperature_c"]
    result["requested_temperature_reduction_c"] = reduction
    result["temperature_reduction_criterion_met"] = reduction >= CRITERIA["minimum_requested_temperature_reduction_c"]
    specimens = {s["specimen_id"]: s for s in request["specimens"]}
    binding = request.get("assessment_binding", {})
    arms = {a: binding.get(a + "_specimen_ids", []) for a in ("candidate", "reference")}
    selected = defaultdict(list)
    excluded = []
    prior_ids = {row.get("evidence_id") for row in prior}
    for row in observations:
        sid, quantity = row.get("specimen_id"), row.get("quantity")
        if row.get("request_id") != request_record["request_id"] or sid not in specimens or quantity not in QUANTITIES:
            excluded.append({"evidence_id": row.get("evidence_id"), "reason": "outside_fixed_assessment_targets"})
            continue
        reason = "old_selection_evidence" if row.get("evidence_id") in prior_ids else _row_reason(row, specimens[sid], request, request_record)
        if reason:
            excluded.append({"evidence_id": row.get("evidence_id"), "specimen_id": sid, "quantity": quantity, "reason": reason})
        else:
            selected[(sid, quantity)].append(row)
    identity_targets = defaultdict(set)
    for target, rows in selected.items():
        for row in rows:
            identity_targets[("evidence", row["evidence_id"])].add(target)
            identity_targets[("measurement", row.get("measurement_id") or row.get("observation_id"))].add(target)
    conflicting = set().union(*(targets for targets in identity_targets.values() if len(targets) > 1)) if identity_targets else set()
    accepted = {}
    for target, rows in selected.items():
        unique = {digest(row): row for row in rows}
        if len(unique) > 1 or target in conflicting:
            excluded.extend({"evidence_id": row["evidence_id"], "specimen_id": target[0], "quantity": target[1], "reason": "conflicting_or_duplicated_target_measurement"} for row in rows)
        else:
            accepted[target] = rows[0]
            excluded.extend({"evidence_id": row["evidence_id"], "specimen_id": target[0], "quantity": target[1], "reason": "exact_duplicate_not_recounted"} for row in rows[1:])
    result["excluded"] = excluded
    result["fixed_outcome_target_count"] = len(specimens) * len(QUANTITIES)
    result["eligible_outcome_target_count"] = len(accepted)
    result["missing_or_ineligible_targets"] = [
        {"specimen_id": sid, "quantity": q} for sid in specimens for q in QUANTITIES if (sid, q) not in accepted
    ]
    verdicts = []
    for quantity, unit in QUANTITIES.items():
        summaries = {}
        for arm, identifiers in arms.items():
            rows = [accepted[(sid, quantity)] for sid in identifiers if (sid, quantity) in accepted]
            summaries[arm] = {
                "mean": sum(r["value"] for r in rows) / len(rows) if rows else None,
                "n_specimens": len(rows), "fixed_specimen_count": len(identifiers),
                "complete": len(rows) == len(identifiers) == CRITERIA["assessment_specimens_per_arm"],
                "evidence_ids": [r["evidence_id"] for r in rows],
                "delivered_temperature_c": [r["delivered_conditions"]["temperature_c"] for r in rows],
                "delivered_pressure_mpa": [r["delivered_conditions"]["pressure_mpa"] for r in rows],
            }
        candidate, reference = summaries["candidate"]["mean"], summaries["reference"]["mean"]
        delta = candidate - reference if candidate is not None and reference is not None else None
        full = all(x["complete"] for x in summaries.values())
        threshold = (-CRITERIA["density_loss_margin_g_cm3"] if quantity == "density_g_cm3" else
                     CRITERIA["porosity_area_fraction_increase_margin"] if quantity == "porosity_area_fraction" else 0.0)
        met = (delta >= threshold if quantity == "density_g_cm3" else delta <= threshold) if full and not issues else None
        result["comparisons"][quantity] = {
            **summaries, "unit": unit, "candidate_minus_reference": delta,
            "contrast_scope": "complete_fresh_arms" if full else "partial_descriptive_means_only",
            "criterion": "candidate-reference >= threshold" if quantity == "density_g_cm3" else "candidate-reference <= threshold",
            "threshold": threshold, "descriptive_criterion_met": met,
        }
        verdicts.append(met)
    if issues:
        result["decision_status"] = "unresolved_integrity"
    elif not result["temperature_reduction_criterion_met"] or False in verdicts:
        result.update(decision_status="fresh_descriptive_failure", recommendation_survived=False)
    elif None in verdicts:
        result["decision_status"] = "unresolved_endpoints"
    else:
        result.update(decision_status="fresh_descriptive_survival", recommendation_survived=True)
    try:
        forecasts = evaluate_fresh_predictions(request_record, observations, quantities=tuple(QUANTITIES), allow_omitted_forecasts=True)
        result["prediction_assessment"] = forecasts
        count = forecasts["target_counts"]
        prediction_integrity = not issues and not forecasts["history_conflicts"]
        requested = commitment["prediction_coordinates"] == "requested_conditions"
        result["prediction_applicability_status"] = "requested_recipe_forecasts" if requested else "indicated_only_without_prospective_recipe_bridge"
        result["complete_eligible_numeric_prediction_assessment"] = bool(
            prediction_integrity and requested and count["requested"] == len(specimens) * len(QUANTITIES)
            and len(accepted) == count["requested"]
            and count["with_scored_observations"] == count["requested"]
            and count["numeric_forecasts"] == count["requested"])
    except (ValueError, TypeError, KeyError) as exc:
        result["prediction_assessment"] = {"status": "invalid_or_unassessable_forecast", "error": str(exc)}
        result["complete_eligible_numeric_prediction_assessment"] = False
    return result
